def transform(grid):
    # Each input cell determines a 3x3 tile. The demo shows foreground
    # marks at the tile corners; tile centers and edge middles stay blank.
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                for dr, dc in ((0, 1), (1, 0), (1, 2), (2, 1)):
                    out[3*r+dr][3*c+dc] = v
    return out

